import React, { useRef } from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { Dialog } from '../../..';

describe('Dialog', () => {
  it('should render', () => {
    render(
      <Dialog.Root
        trigger={<button type="button">Open</button>}
        title={<h2>Dialog Title</h2>}
        actions={
          <Dialog.Close>
            <button type="button">Cancel</button>
          </Dialog.Close>
        }
      >
        <p>Dialog Body</p>
      </Dialog.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Dialog Title')).toBeInTheDocument();
    expect(screen.getByText('Dialog Body')).toBeInTheDocument();
  });

  it('should render with headerImage', () => {
    render(
      <Dialog.Root
        trigger={<button type="button">Open</button>}
        headerHeight="15rem"
        headerImage={
          <div
            data-testid="image-div"
            style={{
              height: '70%',
              backgroundColor: 'rgba(255, 0, 0, 0.3)',
              borderTopLeftRadius: '1.5rem',
              borderTopRightRadius: '1.5rem',
            }}
          />
        }
      >
        <p>Dialog Body</p>
      </Dialog.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByTestId('image-div')).toBeInTheDocument();
  });

  it('should render just with children/body', () => {
    render(
      <Dialog.Root
        trigger={<button type="button">Open</button>}
        variant="noOverlay"
        closeButton={false}
      >
        <p>Dialog Body</p>
      </Dialog.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Dialog Body')).toBeInTheDocument();
  });

  it('should be able to pass refs', () => {
    const UseRef = () => {
      const ref = useRef(null);
      return (
        <Dialog.Root
          trigger={<button type="button">Open</button>}
          variant="noOverlay"
          closeButton={false}
          ref={ref}
        >
          <p>Dialog Body</p>
        </Dialog.Root>
      );
    };
    render(<UseRef />);
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Dialog Body')).toBeInTheDocument();
  });

  it('should be able to pass CSS to the content element', () => {
    render(
      <Dialog.Root
        trigger={<button type="button">Open</button>}
        variant="noOverlay"
        closeButton={false}
        contentCss={{ overflowY: 'hidden' }}
      >
        <p>Dialog Body</p>
      </Dialog.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Dialog Body')).toBeInTheDocument();
  });
  it('should render with variant destructive', () => {
    render(
      <Dialog.Root destructive="critical" trigger={<button type="button">Open</button>}>
        <p>Dialog Body</p>
      </Dialog.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByTestId('destructive')).toBeInTheDocument();
  });
});
